<?php declare(strict_types=1); require_once __DIR__.'/../../config/db.php'; require_once __DIR__.'/../../lib/session.php'; require_once __DIR__.'/../../lib/auth.php'; use function App\Auth\{require_admin,csrf_token}; start_secure_session(); require_admin(); $csrf=csrf_token(); $rides=db()->query('SELECT id,type,from_text,to_text,note,phone,whatsapp,whatsapp_sent,whatsapp_sent_at FROM rides WHERE COALESCE(deleted,0)=0 ORDER BY id DESC LIMIT 100')->fetchAll(); ?>
<!doctype html><title>WhatsApp delivery</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><main class="container py-4"><a href="/admin/index.php">← Admin</a><h1 class="h3 mt-3">WhatsApp ride delivery</h1><table class="table"><thead><tr><th>Ride</th><th>Contact</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rides as $r): ?><tr><td><b><?=htmlspecialchars(strtoupper($r['type']))?></b><br><?=htmlspecialchars($r['from_text'])?> → <?=htmlspecialchars($r['to_text'])?><br><small><?=htmlspecialchars((string)$r['note'])?></small></td><td><?=htmlspecialchars((string)($r['whatsapp']?:$r['phone']))?></td><td><?= $r['whatsapp_sent']?'Sent '.$r['whatsapp_sent_at']:'Not sent' ?></td><td><?php if(!$r['whatsapp_sent']): ?><button class="btn btn-success send" data-id="<?=$r['id']?>">Send to WhatsApp</button><?php endif ?></td></tr><?php endforeach ?></tbody></table></main><script>document.querySelectorAll('.send').forEach(b=>b.onclick=async()=>{b.disabled=true;let r=await fetch('/api/admin/ride_whatsapp_send.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ride_id:b.dataset.id,csrf:'<?=htmlspecialchars($csrf)?>'})});let j=await r.json();if(j.ok)location.reload();else{alert(j.error);b.disabled=false}})</script>
